-- Declared foreign keys for corpus module, added where the database lacks them
-- Generated by metaphor-schema

DO $$
BEGIN
    IF to_regclass('corpus.articles') IS NOT NULL AND to_regclass('corpus.article_categories') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('corpus.articles') AND c.contype = 'f' AND a.attname = 'category_id'
    ) THEN
        ALTER TABLE corpus.articles ADD CONSTRAINT fk_articles_category_id FOREIGN KEY (category_id) REFERENCES corpus.article_categories (id) NOT VALID;
        BEGIN
            ALTER TABLE corpus.articles VALIDATE CONSTRAINT fk_articles_category_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_articles_category_id left NOT VALID: stored rows of corpus.articles reference missing rows';
        END;
    END IF;
END $$;

